import re
from typing import Iterable

from .chapter import AssetLayout, BlockLayout, ParagraphLayout, Reference
from .content import Content
from .mark import Mark, transform2mark

_START_PREFIX_PATTERN = re.compile(r"^\*{1,6}\s+")


class References:
    def __init__(
        self, page_index: int, layouts: Iterable[AssetLayout | ParagraphLayout]
    ) -> None:
        self._page_index: int = page_index
        self._references: list[Reference] = list(
            self._extract_references(page_index, layouts)
        )
        self._mark2reference: dict[str | Mark, Reference] = {}
        for reference in self._references:
            mark = reference.mark
            if mark not in self._mark2reference:
                self._mark2reference[mark] = reference

    @property
    def page_index(self) -> int:
        return self._page_index

    def get(self, mark: str | Mark) -> Reference | None:
        return self._mark2reference.get(mark, None)

    def _extract_references(
        self, page_index: int, layouts: Iterable[AssetLayout | ParagraphLayout]
    ):
        order: int = 1
        reference: Reference | None = None
        for item in self._iter_and_inject_marks(layouts):
            if isinstance(item, Mark | str):
                if reference:
                    yield reference
                reference = Reference(
                    page_index=page_index,
                    order=order,
                    mark=item,
                    layouts=[],
                )
                order += 1
            elif reference:
                reference.layouts.append(item)
            else:
                # TODO: 多余的内容可能是上一页的跨页页脚注释 / 引用，也可能是必须忽略的多余内容。
                #       此处没有能力进行判断，以后看看有什么好办法。
                pass
        if reference:
            yield reference

    def _iter_and_inject_marks(self, layouts: Iterable[AssetLayout | ParagraphLayout]):
        for layout in layouts:
            if isinstance(layout, AssetLayout):
                yield layout
            elif isinstance(layout, ParagraphLayout):
                for mark, sub_layout in self._split_paragraph_by_marks(layout):
                    if mark is not None:
                        yield mark
                    yield sub_layout

    def _split_paragraph_by_marks(self, to_split_layout: ParagraphLayout):
        mark_layout: tuple[Mark | str | None, ParagraphLayout] = (
            None,
            ParagraphLayout(
                ref=to_split_layout.ref,
                level=-1,
                blocks=[],
            ),
        )
        for block in to_split_layout.blocks:
            mark, content = self._extract_head_mark(block.content)
            if mark is None:
                mark_layout[1].blocks.append(block)
            else:
                if mark_layout[1].blocks:
                    yield mark_layout
                mark_layout = (
                    mark,
                    ParagraphLayout(
                        ref=to_split_layout.ref,
                        level=-1,
                        blocks=[
                            BlockLayout(
                                page_index=block.page_index,
                                order=block.order,
                                det=block.det,
                                content=content,
                            )
                        ],
                    ),
                )
        if mark_layout[1].blocks:
            yield mark_layout

    def _extract_head_mark(self, content: Content) -> tuple[Mark | str | None, Content]:
        if not content or not isinstance(content[0], str):
            return None, content
        head_text = content[0].lstrip()
        if not head_text:
            return None, content

        mark: Mark | str | None = None
        rest: str = ""
        matched = _START_PREFIX_PATTERN.match(head_text)
        new_content: Content = content[1:]

        if matched:
            prefix = matched.group(0)
            mark = prefix.strip()
            rest = head_text[matched.end() :].lstrip()
        else:
            mark = transform2mark(head_text[0])
            if mark is not None:
                rest = head_text[1:].lstrip()

        rest = rest.lstrip()
        if rest:
            new_content = [rest] + content[1:]

        return mark, new_content

from .chapter import AssetLayout, Chapter, ParagraphLayout, search_references_in_chapter
from .content import Content, expand_text_in_content

_LEFT_ONLY_ASCII_TO_FULLWIDTH = {
    ",": "，",
    ";": "；",
    "?": "？",
    "!": "！",
}

_BOTH_SIDES_ASCII_TO_FULLWIDTH = {
    ":": "：",
}


# to fix https://github.com/oomol-lab/pdf-craft/issues/310
def normalize_punctuation_in_chapter(chapter: Chapter) -> Chapter:
    _normalize_layouts(chapter.layouts)
    for ref in search_references_in_chapter(chapter):
        _normalize_layouts(ref.layouts)
    return chapter


def _normalize_layouts(layouts: list[ParagraphLayout | AssetLayout]) -> None:
    for layout in layouts:
        if isinstance(layout, ParagraphLayout):
            for block in layout.blocks:
                _normalize_content(block.content)
        elif isinstance(layout, AssetLayout):
            _normalize_content(layout.title)
            _normalize_content(layout.caption)


def _normalize_content(content: Content) -> None:
    segments: list[str] = []

    def collect_text_segments(text: str) -> str:
        segments.append(text)
        return text

    expand_text_in_content(
        content=content,
        expand=lambda text: (collect_text_segments(text),),
    )

    normalized_segments = _normalize_segments(segments)
    if normalized_segments is None:
        return

    segment_index = 0

    def replace_text(_: str):
        nonlocal segment_index
        text = normalized_segments[segment_index]
        segment_index += 1
        return (text,)

    expand_text_in_content(
        content=content,
        expand=replace_text,
    )


def _normalize_segments(segments: list[str]) -> list[str] | None:
    if not segments:
        return None

    full_chars: list[str] = []
    owners: list[tuple[int, int]] = []
    for segment_idx, text in enumerate(segments):
        for char_idx, char in enumerate(text):
            full_chars.append(char)
            owners.append((segment_idx, char_idx))

    segment_chars = [list(text) for text in segments]
    changed = False

    for idx, char in enumerate(full_chars):
        left = _search_near_char(full_chars, idx, reverse=True)
        if left is None:
            continue

        mapped = _LEFT_ONLY_ASCII_TO_FULLWIDTH.get(char)
        if mapped is not None:
            if not _is_han_char(left):
                continue
        else:
            mapped = _BOTH_SIDES_ASCII_TO_FULLWIDTH.get(char)
            if mapped is None:
                continue
            right = _search_near_char(full_chars, idx, reverse=False)
            if right is None or not (_is_han_char(left) and _is_han_char(right)):
                continue

        owner_segment_idx, owner_char_idx = owners[idx]
        segment_chars[owner_segment_idx][owner_char_idx] = mapped
        changed = True

    if not changed:
        return None

    return ["".join(chars) for chars in segment_chars]


def _search_near_char(chars: list[str], center: int, reverse: bool) -> str | None:
    if reverse:
        indexes = range(center - 1, -1, -1)
    else:
        indexes = range(center + 1, len(chars))

    for idx in indexes:
        char = chars[idx]
        if char.isspace():
            continue
        return char
    return None


def _is_han_char(char: str) -> bool:
    code = ord(char)
    return (
        0x3400 <= code <= 0x4DBF  # CJK Unified Ideographs Extension A
        or 0x4E00 <= code <= 0x9FFF  # CJK Unified Ideographs
        or 0xF900 <= code <= 0xFAFF  # CJK Compatibility Ideographs
        or 0x20000 <= code <= 0x2A6DF  # CJK Unified Ideographs Extension B
        or 0x2A700 <= code <= 0x2B73F  # CJK Unified Ideographs Extension C
        or 0x2B740 <= code <= 0x2B81F  # CJK Unified Ideographs Extension D
        or 0x2B820 <= code <= 0x2CEAF  # CJK Unified Ideographs Extension E
        or 0x2CEB0 <= code <= 0x2EBEF  # CJK Unified Ideographs Extension F/G
    )

from pathlib import Path
from typing import Generator

from ...common import XMLReader, save_xml
from ...pdf import TITLE_TAGS, Page, decode
from ..toc import Toc, TocInfo, iter_toc
from .analyse_level import analyse_chapter_internal_levels
from .chapter import (
    AssetLayout,
    BlockLayout,
    Chapter,
    ParagraphLayout,
    Reference,
    encode,
)
from .content import expand_text_in_content, join_texts_in_content
from .jointer import Jointer
from .mark import Mark, search_marks
from .punctuation import normalize_punctuation_in_chapter
from .reference import References


def generate_chapter_files(pages_path: Path, chapters_path: Path, toc: TocInfo):
    chapters_path.mkdir(parents=True, exist_ok=True)
    for chapter_file in chapters_path.glob("chapter_*.xml"):
        chapter_file.unlink()

    for chapter in _generate_chapters(
        pages_path=pages_path,
        toc=toc,
    ):
        tail: str
        if chapter.id is None:
            tail = "head"
        else:
            tail = f"{chapter.id}"

        chapter = normalize_punctuation_in_chapter(chapter)
        chapter = analyse_chapter_internal_levels(chapter)
        chapter_file = chapters_path / f"chapter_{tail}.xml"
        chapter_element = encode(chapter)
        save_xml(chapter_element, chapter_file)


def _generate_chapters(
    pages_path: Path, toc: TocInfo
) -> Generator[Chapter, None, None]:
    chapter: Chapter | None = None
    ref2toc: dict[tuple[int, int], Toc] = {}

    for item in iter_toc(toc.content):
        ref2toc[(item.page_index, item.order)] = item

    for layout in _extract_body_layouts(pages_path, toc):
        matched_toc = False
        if (
            isinstance(layout, ParagraphLayout)
            and layout.blocks
            and layout.ref in TITLE_TAGS
        ):
            item: Toc | None = None
            for block in layout.blocks:
                item = ref2toc.get((block.page_index, block.order), None)
                if item:
                    break
            if item:
                if chapter:
                    yield chapter
                chapter = Chapter(
                    id=item.id,
                    level=item.level,
                    layouts=[layout],
                )
                matched_toc = True

        if not matched_toc:
            if chapter is None:
                max_level = max((t.level for t in iter_toc(toc.content)), default=0)
                chapter = Chapter(
                    id=None,
                    level=max_level,  # 防止章节标题盖过其他
                    layouts=[],
                )
            chapter.layouts.append(layout)

    if chapter:
        yield chapter


def _extract_body_layouts(pages_path: Path, toc: TocInfo):
    pages: XMLReader[Page] = XMLReader(
        prefix="page",
        dir_path=pages_path,
        decode=decode,
    )
    toc_page_indexes = set(toc.page_indexes)
    body_jointer = Jointer(
        (
            (p.index, p.body_layouts)
            for p in pages.read()
            if p.index not in toc_page_indexes
        )
    )
    footnotes_jointer = Jointer(
        (
            (p.index, p.footnotes_layouts)
            for p in pages.read()
            if p.index not in toc_page_indexes
        )
    )
    references_generator = _extract_page_references(footnotes_jointer)
    current_references: References | None = next(references_generator, None)

    def get_references(page_index: int) -> References | None:
        nonlocal current_references
        while (
            current_references is not None
            and current_references.page_index < page_index
        ):
            current_references = next(references_generator, None)
        if (
            current_references is not None
            and current_references.page_index == page_index
        ):
            return current_references
        return None

    for layout in body_jointer.execute():
        if isinstance(layout, ParagraphLayout):
            for block in layout.blocks:
                references = get_references(block.page_index)
                if references:
                    _replace_mark_with_reference(references, block)
                join_texts_in_content(block.content)

        yield layout


def _extract_page_references(jointer: Jointer) -> Generator[References, None, None]:
    last_page_index: int = -1
    layout_buffer: list[AssetLayout | ParagraphLayout] = []

    for layout in jointer.execute():
        page_index = _page_index_from_layout(layout)
        if page_index != last_page_index:
            if layout_buffer:
                yield References(
                    page_index=last_page_index,
                    layouts=layout_buffer,
                )
            last_page_index = page_index
            layout_buffer = []
        layout_buffer.append(layout)

    if layout_buffer:
        yield References(
            page_index=last_page_index,
            layouts=layout_buffer,
        )


def _page_index_from_layout(layout: AssetLayout | ParagraphLayout) -> int:
    if isinstance(layout, ParagraphLayout):
        if not layout.blocks:
            raise ValueError("ParagraphLayout has no blocks to get page index")
        return layout.blocks[0].page_index
    elif isinstance(layout, AssetLayout):
        return layout.page_index
    else:
        raise TypeError(f"Unknown layout type: {type(layout).__name__}")


def _replace_mark_with_reference(references: References, block: BlockLayout):
    def expand(text: str):
        for item in search_marks(text):
            reference: Reference | None = None
            if isinstance(item, Mark):
                reference = references.get(item)
            if reference:
                yield reference
            else:
                yield str(item)

    expand_text_in_content(
        content=block.content,
        expand=expand,
    )

from typing import Callable, Generator, Iterable

from ...markdown.paragraph import HTMLTag
from .chapter import BlockMember

Content = list[str | BlockMember | HTMLTag[BlockMember]]


def first(content: Content) -> None | str | BlockMember:
    if not content:
        return None
    element = content[0]
    if isinstance(element, HTMLTag):
        return first(element.children)
    else:
        return element


def last(content: Content) -> None | str | BlockMember:
    if not content:
        return None
    element = content[-1]
    if isinstance(element, HTMLTag):
        return last(element.children)
    else:
        return element


def join_texts_in_content(content: Content) -> None:
    for sub_content in _search_content(content):
        i: int = 0
        while i < len(sub_content) - 1:
            part1 = sub_content[i]
            part2 = sub_content[i + 1]
            if isinstance(part1, str) and isinstance(part2, str):
                sub_content[i] = part1 + part2
                del sub_content[i + 1]
            else:
                i += 1


def expand_text_in_content(
    content: Content,
    expand: Callable[[str], Iterable[str | BlockMember]],
) -> None:
    for sub_content in _search_content(content):
        i: int = 0
        while i < len(sub_content):
            part = sub_content[i]
            if isinstance(part, str):
                del sub_content[i]
                for expanded_part in expand(part):
                    sub_content.insert(i, expanded_part)
                    i += 1
            else:
                i += 1


def _search_content(content: Content) -> Generator[Content, None, None]:
    for child in content:
        if isinstance(child, HTMLTag):
            yield from _search_content(child.children)
    yield content

from dataclasses import dataclass
from typing import Generator, Iterable, cast
from xml.etree.ElementTree import Element

from ...common import ASSET_TAGS, AssetRef, indent
from ...expression import ExpressionKind, decode_expression_kind, encode_expression_kind
from ...markdown.paragraph import HTMLTag, flatten
from ...markdown.paragraph import decode as decode_content
from ...markdown.paragraph import encode as encode_content
from .mark import Mark


@dataclass
class Chapter:
    id: int | None
    level: int
    layouts: list["ParagraphLayout | AssetLayout"]


@dataclass
class ParagraphLayout:
    ref: str
    level: int
    blocks: list["BlockLayout"]


@dataclass
class InlineExpression:
    kind: ExpressionKind
    content: str


@dataclass
class Reference:
    page_index: int
    order: int
    mark: str | Mark
    layouts: list["AssetLayout | ParagraphLayout"]

    @property
    def id(self) -> tuple[int, int]:
        return (self.page_index, self.order)


BlockMember = InlineExpression | Reference
RefIdMap = dict[tuple[int, int], int]


@dataclass
class AssetLayout:
    page_index: int
    ref: AssetRef
    det: tuple[int, int, int, int]
    title: list[str | BlockMember | HTMLTag[BlockMember]]
    content: list[str | BlockMember | HTMLTag[BlockMember]]
    caption: list[str | BlockMember | HTMLTag[BlockMember]]
    hash: str | None


@dataclass
class BlockLayout:
    page_index: int
    order: int
    det: tuple[int, int, int, int]
    content: list[str | BlockMember | HTMLTag[BlockMember]]


def search_references_in_chapter(chapter: Chapter) -> Generator[Reference, None, None]:
    seen: set[tuple[int, int]] = set()
    for part in _search_parts_in_chapter(chapter):
        if isinstance(part, Reference):
            ref_id = part.id
            if ref_id not in seen:
                seen.add(ref_id)
                yield part


def references_to_map(references: Iterable[Reference]) -> RefIdMap:
    ref_id_to_number = {}
    for i, ref in enumerate(references, 1):
        ref_id_to_number[ref.id] = i
    return ref_id_to_number


def decode(element: Element) -> Chapter:
    references_el = element.find("references")
    references_map: dict[tuple[int, int], Reference] = {}
    if references_el is not None:
        for ref_el in references_el.findall("ref"):
            reference = _decode_reference(ref_el)
            references_map[reference.id] = reference

    id_attr = element.get("id")
    id_value = int(id_attr) if id_attr is not None else None

    level_attr = element.get("level")
    level = int(level_attr) if level_attr is not None else -1

    body_el = element.find("body")
    if body_el is None:
        raise ValueError("<chapter> missing required <body> element")

    layouts: list[ParagraphLayout | AssetLayout] = []
    for child in list(body_el):
        tag = child.tag
        if tag == "asset":
            layouts.append(_decode_asset(child))
        elif tag == "paragraph":
            layouts.append(_decode_paragraph(child, references_map))

    return Chapter(
        id=id_value,
        level=level,
        layouts=layouts,
    )


def encode(chapter: Chapter) -> Element:
    root = Element("chapter")

    if chapter.id is not None:
        root.set("id", str(chapter.id))

    if chapter.level != -1:
        root.set("level", str(chapter.level))

    body_el = Element("body")
    for layout in chapter.layouts:
        if isinstance(layout, AssetLayout):
            body_el.append(_encode_asset(layout))
        else:
            body_el.append(_encode_paragraph(layout))

    root.append(body_el)
    references = list(search_references_in_chapter(chapter))
    references.sort(key=lambda ref: ref.id)

    if references:
        references_el = Element("references")
        for ref in references:
            references_el.append(_encode_reference(ref))
        root.append(references_el)

    return indent(root)


def _search_parts_in_chapter(chapter: Chapter):
    for layout in chapter.layouts:
        if isinstance(layout, ParagraphLayout):
            for block in layout.blocks:
                yield from flatten(block.content)


def _decode_asset(element: Element) -> AssetLayout:
    ref_attr = element.get("ref")
    if ref_attr is None:
        raise ValueError("<asset> missing required attribute 'ref'")
    if ref_attr not in ASSET_TAGS:
        raise ValueError(
            f"<asset> attribute 'ref' must be one of {ASSET_TAGS}, got: {ref_attr}"
        )
    page_index_attr = element.get("page_index")
    if page_index_attr is None:
        raise ValueError("<asset> missing required attribute 'page_index'")
    try:
        page_index = int(page_index_attr)
    except ValueError as e:
        raise ValueError(
            f"<asset> attribute 'page_index' must be int, got: {page_index_attr}"
        ) from e

    det_str = element.get("det")
    if det_str is None:
        raise ValueError("<asset> missing required attribute 'det'")
    det = _parse_det(det_str, context="<asset>@det")

    hash_value = element.get("hash")

    def decode_block_member(child: Element) -> BlockMember:
        if child.tag == "ref":
            raise ValueError("<asset> cannot contain <ref> elements")
        elif child.tag == "inline_expr":
            kind_attr = child.get("kind")
            if kind_attr is None:
                raise ValueError(
                    "<asset><inline_expr> missing required attribute 'kind'"
                )
            kind = decode_expression_kind(kind_attr)
            expr_text = child.text if child.text is not None else ""
            return InlineExpression(kind=kind, content=expr_text)
        else:
            raise ValueError(f"<asset> contains unknown element: <{child.tag}>")

    title_el = element.find("title")
    title = (
        decode_content(title_el, decode_block_member) if title_el is not None else []
    )

    content_el = element.find("content")
    content = (
        decode_content(content_el, decode_block_member)
        if content_el is not None
        else []
    )

    caption_el = element.find("caption")
    caption = (
        decode_content(caption_el, decode_block_member)
        if caption_el is not None
        else []
    )

    return AssetLayout(
        page_index=page_index,
        ref=cast(AssetRef, ref_attr),
        det=det,
        title=title,
        content=content,
        caption=caption,
        hash=hash_value,
    )


def _encode_asset(layout: AssetLayout) -> Element:
    el = Element("asset")
    el.set("ref", layout.ref)
    el.set("page_index", str(layout.page_index))
    el.set("det", ",".join(map(str, layout.det)))
    if layout.hash is not None:
        el.set("hash", layout.hash)

    if layout.title:
        title_el = Element("title")
        encode_content(
            root=title_el,
            children=layout.title,
            encode_payload=_encode_block_member,
        )
        el.append(title_el)

    if layout.content:
        content_el = Element("content")
        encode_content(
            root=content_el,
            children=layout.content,
            encode_payload=_encode_block_member,
        )
        el.append(content_el)

    if layout.caption:
        caption_el = Element("caption")
        encode_content(
            root=caption_el,
            children=layout.caption,
            encode_payload=_encode_block_member,
        )
        el.append(caption_el)

    return el


def _decode_paragraph(
    element: Element, references_map: dict[tuple[int, int], Reference] | None = None
) -> ParagraphLayout:
    ref_attr = element.get("ref")
    if ref_attr is None:
        raise ValueError("<paragraph> missing required attribute 'ref'")

    level_attr = element.get("level")
    level = int(level_attr) if level_attr is not None else -1

    blocks = _decode_block_elements(
        parent=element,
        context_tag="paragraph",
        references_map=references_map,
    )
    return ParagraphLayout(ref=ref_attr, level=level, blocks=blocks)


def _encode_paragraph(layout: ParagraphLayout) -> Element:
    el = Element("paragraph")
    el.set("ref", layout.ref)
    if layout.level != -1:
        el.set("level", str(layout.level))
    for block in layout.blocks:
        el.append(_encode_block_element(block))
    return el


def _parse_det(det_str: str, context: str) -> tuple[int, int, int, int]:
    try:
        det_list = list(map(int, det_str.split(",")))
    except Exception as e:
        raise ValueError(
            f"{context}: det must be comma-separated integers, got: {det_str}"
        ) from e
    if len(det_list) != 4:
        raise ValueError(f"{context}: det must have 4 values, got {len(det_list)}")
    return (det_list[0], det_list[1], det_list[2], det_list[3])


def _decode_block_elements(
    parent: Element,
    context_tag: str,
    references_map: dict[tuple[int, int], Reference] | None = None,
) -> list[BlockLayout]:
    blocks: list[BlockLayout] = []
    for block_el in parent.findall("block"):
        page_index_attr = block_el.get("page_index")
        if page_index_attr is None:
            raise ValueError(
                f"<{context_tag}><block> missing required attribute 'page_index'"
            )
        try:
            page_index = int(page_index_attr)
        except ValueError as e:
            raise ValueError(
                f"<{context_tag}><block> attribute 'page_index' must be int, got: {page_index_attr}"
            ) from e

        order_attr = block_el.get("order")
        if order_attr is None:
            raise ValueError(
                f"<{context_tag}><block> missing required attribute 'order'"
            )
        try:
            order = int(order_attr)
        except ValueError as e:
            raise ValueError(
                f"<{context_tag}><block> attribute 'order' must be int, got: {order_attr}"
            ) from e

        det_str = block_el.get("det")
        if det_str is None:
            raise ValueError(f"<{context_tag}><block> missing required attribute 'det'")
        det = _parse_det(det_str, context=f"<{context_tag}><block>@det")

        def decode_block_member(child: Element) -> BlockMember:
            if child.tag == "ref":
                ref_id = child.get("id")
                if ref_id is None:
                    raise ValueError(
                        f"<{context_tag}><block><ref> missing required attribute 'id'"
                    )

                try:
                    parts = ref_id.split("-")
                    if len(parts) != 2:
                        raise ValueError(
                            f"<{context_tag}><block><ref> attribute 'id' must be in format 'page-order'"
                        )
                    ref_page_index = int(parts[0])
                    ref_order = int(parts[1])
                except ValueError as e:
                    raise ValueError(
                        f"<{context_tag}><block><ref> attribute 'id' must contain valid integers"
                    ) from e

                if references_map is not None:
                    ref_key = (ref_page_index, ref_order)
                    if ref_key in references_map:
                        return references_map[ref_key]
                    else:
                        raise ValueError(
                            f"<{context_tag}><block><ref> references undefined reference: {ref_id}"
                        )
                else:
                    raise ValueError(
                        f"<{context_tag}><block><ref> cannot resolve reference without references_map"
                    )

            elif child.tag == "inline_expr":
                kind_attr = child.get("kind")
                if kind_attr is None:
                    raise ValueError(
                        f"<{context_tag}><block><inline_expr> missing required attribute 'kind'"
                    )
                kind = decode_expression_kind(kind_attr)
                expr_text = child.text if child.text is not None else ""
                return InlineExpression(kind=kind, content=expr_text)

            else:
                raise ValueError(
                    f"<{context_tag}><block> contains unknown element: <{child.tag}>"
                )

        blocks.append(
            BlockLayout(
                page_index=page_index,
                order=order,
                det=det,
                content=decode_content(block_el, decode_block_member),
            )
        )

    return blocks


def _encode_block_element(block: BlockLayout) -> Element:
    block_el = Element("block")
    block_el.set("page_index", str(block.page_index))
    block_el.set("order", str(block.order))
    block_el.set("det", ",".join(map(str, block.det)))
    encode_content(
        root=block_el,
        children=block.content,
        encode_payload=_encode_block_member,
    )
    return block_el


def _encode_block_member(part: BlockMember) -> Element:
    if isinstance(part, InlineExpression):
        expr_el = Element("inline_expr")
        expr_el.set("kind", encode_expression_kind(part.kind))
        expr_el.text = part.content
        return expr_el

    elif isinstance(part, Reference):
        ref_el = Element("ref")
        ref_el.set("id", f"{part.page_index}-{part.order}")
        return ref_el

    else:
        raise ValueError("Unknown BlockMember type")


def _encode_reference(ref: Reference) -> Element:
    ref_el = Element("ref")
    ref_el.set("id", f"{ref.page_index}-{ref.order}")

    mark_el = Element("mark")
    mark_el.text = str(ref.mark)
    ref_el.append(mark_el)

    for layout in ref.layouts:
        if isinstance(layout, AssetLayout):
            ref_el.append(_encode_asset(layout))
        else:
            ref_el.append(_encode_paragraph(layout))

    return ref_el


def _decode_reference(element: Element) -> Reference:
    ref_id = element.get("id")
    if ref_id is None:
        raise ValueError("<references><ref> missing required attribute 'id'")

    try:
        parts = ref_id.split("-")
        if len(parts) != 2:
            raise ValueError(
                "<references><ref> attribute 'id' must be in format 'page-order'"
            )
        page_index = int(parts[0])
        order = int(parts[1])
    except ValueError as e:
        raise ValueError(
            "<references><ref> attribute 'id' must contain valid integers"
        ) from e

    mark_el = element.find("mark")
    if mark_el is None or mark_el.text is None:
        raise ValueError("<references><ref> missing required <mark> element")
    mark_text = mark_el.text

    from .mark import transform2mark

    mark = transform2mark(mark_text)
    if mark is None:
        # 如果不是特殊标记，就使用原始字符串
        mark = mark_text

    layouts: list[AssetLayout | ParagraphLayout] = []
    for child in element:
        if child.tag == "mark":
            continue
        elif child.tag == "asset":
            layouts.append(_decode_asset(child))
        elif child.tag == "paragraph":
            layouts.append(_decode_paragraph(child, references_map=None))

    return Reference(
        page_index=page_index,
        order=order,
        mark=mark,
        layouts=layouts,
    )

from pathlib import Path
from shutil import copy2
from typing import Callable, Generator, Iterable

from ...expression import ExpressionKind, to_markdown_string
from ...pdf import TITLE_TAGS
from ...extractor.chapter import (
    AssetLayout,
    BlockMember,
    InlineExpression,
    ParagraphLayout,
    Reference,
    RefIdMap,
)
from ..paragraph import render_markdown_paragraph
from .table import render_table_content

_MAX_TOC_LEVELS = 3
_MAX_TITLE_LEVELS = 6


def render_layouts(
    layouts: Iterable[ParagraphLayout | AssetLayout],
    assets_path: Path,
    output_assets_path: Path,
    asset_ref_path: Path,
    toc_level: int,
    ref_id_to_number: RefIdMap | None = None,
) -> Generator[str, None, None]:
    is_first_layout = True
    toc_level = min(toc_level, _MAX_TOC_LEVELS - 1)

    for layout in layouts:
        if is_first_layout:
            is_first_layout = False
        else:
            yield "\n\n"
        if isinstance(layout, AssetLayout):
            yield from _render_asset(
                asset=layout,
                assets_path=assets_path,
                output_assets_path=output_assets_path,
                asset_ref_path=asset_ref_path,
                ref_id_to_number=ref_id_to_number,
            )
        elif isinstance(layout, ParagraphLayout):
            yield from render_paragraph(
                paragraph=layout,
                toc_level=toc_level,
                ref_id_to_number=ref_id_to_number,
            )


def render_paragraph(
    paragraph: ParagraphLayout, toc_level: int, ref_id_to_number: RefIdMap | None = None
) -> Generator[str, None, None]:
    if paragraph.level >= 0 and paragraph.ref in TITLE_TAGS:
        level = min(toc_level + paragraph.level, _MAX_TITLE_LEVELS)
        for _ in range(level + 1):  # level 0 对应 1 个 #
            yield "#"
        yield " "

    def render_member(part: BlockMember | str) -> Generator[str, None, None]:
        if isinstance(part, str):
            yield to_markdown_string(
                kind=ExpressionKind.TEXT,
                content=part,
            )
        elif isinstance(part, InlineExpression):
            latex_content = part.content.strip()
            if latex_content:
                yield to_markdown_string(
                    kind=part.kind,
                    content=latex_content,
                )
        elif ref_id_to_number and isinstance(part, Reference):
            ref_number = ref_id_to_number.get(part.id, 1)
            yield "[^"
            yield str(ref_number)
            yield "]"

    for block in paragraph.blocks:
        yield from render_markdown_paragraph(
            children=block.content,
            render_payload=render_member,
        )


_MemberRender = Callable[[BlockMember | str], Iterable[str]]


def _render_asset(
    asset: AssetLayout,
    assets_path: Path,
    output_assets_path: Path,
    asset_ref_path: Path,
    ref_id_to_number: RefIdMap | None = None,
) -> Generator[str, None, None]:
    def render_member(part: BlockMember | str) -> Generator[str, None, None]:
        if isinstance(part, str):
            yield to_markdown_string(
                kind=ExpressionKind.TEXT,
                content=part,
            )
        elif isinstance(part, InlineExpression):
            latex_content = part.content.strip()
            if latex_content:
                yield to_markdown_string(
                    kind=part.kind,
                    content=latex_content,
                )
        elif ref_id_to_number and isinstance(part, Reference):
            ref_number = ref_id_to_number.get(part.id, 1)
            yield "[^"
            yield str(ref_number)
            yield "]"

    has_content = False

    if asset.title:
        title_str = "".join(
            render_markdown_paragraph(
                children=asset.title,
                render_payload=render_member,
            )
        ).strip()
        if title_str:
            yield title_str
            has_content = True
